sys_script_include.script:
var LeaveBalanceManager = Class.create();
LeaveBalanceManager.prototype = {
    initialize: function() {
        this.balanceTable = 'x_1800027_leve_sys_leave_balance';
        this.leaveTypeTable = 'x_1800027_leve_sys_leave_type';
    },

    resetAnnualBalances: function() {
        var result = {
            success: true,
            message: '',
            updated: 0,
            errors: 0
        };

        try {
            // Get all leave types
            var leaveTypes = {};
            var leaveTypeGR = new GlideRecordSecure(this.leaveTypeTable);
            leaveTypeGR.query();
            while (leaveTypeGR.next()) {
                leaveTypes[leaveTypeGR.getUniqueValue()] = {
                    name: leaveTypeGR.name.toString(),
                    default_balance: parseFloat(leaveTypeGR.default_annual_entitlement.toString()) || 0,
                    carry_forward_allowed: leaveTypeGR.carry_forward_allowed.toString() === 'true',
                    max_carry_forward: parseFloat(leaveTypeGR.max_carry_forward.toString()) || 0
                };
            }

            // Process all employees with leave balances
            var balanceGR = new GlideRecordSecure(this.balanceTable);
            balanceGR.query();

            while (balanceGR.next()) {
                try {
                    var leaveTypeId = balanceGR.leave_type.toString();
                    var leaveType = leaveTypes[leaveTypeId];

                    if (!leaveType) {
                        continue;
                    }

                    // Apply reset policy
                    var currentBalance = parseFloat(balanceGR.available_balance.toString()) || 0;
                    var newBalance = leaveType.default_balance;
                    var carryForward = 0;

                    // Apply carry-forward if allowed
                    if (leaveType.carry_forward_allowed && currentBalance > 0) {
                        carryForward = Math.min(currentBalance, leaveType.max_carry_forward);
                        newBalance += carryForward;
                    }

                    // Update balance
                    balanceGR.carry_forward_balance = carryForward;
                    balanceGR.available_balance = newBalance;
                    balanceGR.last_reset_date = new GlideDateTime();
                    balanceGR.update();

                    result.updated++;
                } catch (e) {
                    result.errors++;
                    gs.error("Error updating leave balance: " + e);
                }
            }

            result.message = "Successfully updated " + result.updated + " leave balances with " + result.errors + " errors.";
        } catch (e) {
            result.success = false;
            result.message = "Error updating leave balances: " + e;
            gs.error(result.message);
        }

        return result;
    },

    createMissingBalances: function() {
        var result = {
            success: true,
            message: '',
            created: 0,
            errors: 0
        };

        try {
            // Get all leave types
            var leaveTypes = [];
            var leaveTypeGR = new GlideRecordSecure(this.leaveTypeTable);
            leaveTypeGR.query();
            while (leaveTypeGR.next()) {
                leaveTypes.push({
                    sys_id: leaveTypeGR.getUniqueValue(),
                    name: leaveTypeGR.name.toString(),
                    default_balance: parseFloat(leaveTypeGR.default_annual_entitlement.toString()) || 0
                });
            }

            // Get all active employees
            var userGR = new GlideRecordSecure('sys_user');
            userGR.addActiveQuery();
            userGR.query();

            while (userGR.next()) {
                var userId = userGR.getUniqueValue();

                // For each leave type, check if balance exists
                for (var i = 0; i < leaveTypes.length; i++) {
                    var leaveType = leaveTypes[i];

                    // Check if balance exists
                    var balanceGR = new GlideRecordSecure(this.balanceTable);
                    balanceGR.addQuery('employee', userId);
                    balanceGR.addQuery('leave_type', leaveType.sys_id);
                    balanceGR.query();

                    if (!balanceGR.next()) {
                        // Create new balance
                        try {
                            balanceGR = new GlideRecordSecure(this.balanceTable);
                            balanceGR.initialize();
                            balanceGR.employee = userId;
                            balanceGR.leave_type = leaveType.sys_id;
                            balanceGR.available_balance = leaveType.default_balance;
                            balanceGR.carry_forward_balance = 0;
                            balanceGR.last_reset_date = new GlideDateTime();
                            balanceGR.insert();

                            result.created++;
                        } catch (e) {
                            result.errors++;
                            gs.error("Error creating leave balance: " + e);
                        }
                    }
                }
            }

            result.message = "Successfully created " + result.created + " leave balances with " + result.errors + " errors.";
        } catch (e) {
            result.success = false;
            result.message = "Error creating leave balances: " + e;
            gs.error(result.message);
        }

        return result;
    },

    type: 'LeaveBalanceManager'
};
